import{_ as l,a0 as n,w as p,s as u,ao as a,I as s,x as o,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"計算機正常運行最大的威脅是什麼？是員工 | LCTT x X-CMD","titleTemplate":false,"description":"計算機正常運行最大的威脅是什麼？是員工 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"計算機正常運行最大的威脅是什麼？是員工 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"計算機正常運行最大的威脅是什麼？是員工 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20191010 The biggest risk to uptime- Your staff","title":"計算機正常運行最大的威脅是什麼？是員工","tag":"202101","desc":""},"relativePath":"202101/20191010 The biggest risk to uptime- Your staff.md","filePath":"[post].md"}'),f={name:"202101/20191010 The biggest risk to uptime- Your staff.md"};function m(d,t,T,g,w,k){const e=n("Link");return p(),u("div",null,[t[18]||(t[18]=a('<h1 id="計算機正常運行最大的威脅是什麼-是員工" tabindex="-1">計算機正常運行最大的威脅是什麼？是員工 <a class="header-anchor" href="#計算機正常運行最大的威脅是什麼-是員工" aria-label="Permalink to “計算機正常運行最大的威脅是什麼？是員工”">​</a></h1><blockquote><p>一項新研究發現，人為失誤是引發停機時間的首要原因。你想像一下那是什麼場景。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/07/9_how-well-do-you-know-your-staff_head-in-sand-100765388-large.jpg" alt=""></p><p>之前有一個很老的笑話：“是人都會犯錯，但是要真正把事情搞砸，你還缺台計算機。” 現在情況正好相反了，現如今，數據中心設備的可靠性已經得到了極大的提升，反而是使用設備的人員素質沒能跟上，從而給計算機正常運行帶來了很大的威脅。</p><p><ruby>正常運行時間協會<rt>Uptime Institute</rt></ruby>對數千名 IT 專業人員一整年發生的故障事件進行了調查，得出結論表示絕大多數的數據中心故障是由於人為錯誤造成的，人為錯誤導致的故障率為 70%-75%。</p><p>而且有些故障很嚴重。調查發現，超過 30% 的 IT 服務與數據中心運營商經歷了他們稱之為是“嚴重服務退化”的停機事故。2019 年有 10% 的受訪者稱他們最近的事故造成的損失超過 100 萬美元。</p><p>在正常運行時間協會在 2019 年 4 月的調查中，60% 的受訪者認為，對於最近發生的重大停機事件，他們本可以通過更好的管理/流程或配置進行防止。而對於損失超過 100 萬美元的故障事件，這一數字躍升至 74%。</p><p>正常運行時間協會認為，導致故障事件發生的最終的錯誤不一定是員工，而是令人失望的管理。</p>',8)),s("p",null,[t[1]||(t[1]=o("“這個行業仍然嚴重依賴於人工去完成一些最基礎和最重要的工作，易受人為錯誤的影響，這一點無法避免，也許可做的防錯/防災措施很有限。”正常運行時間協會期刊的主編 Kevin Heslin 在一篇",-1)),r(e,{href:"https://journal.uptimeinstitute.com/how-to-avoid-outages-try-harder/"},{default:i(()=>[...t[0]||(t[0]=[o("Blog文章",-1)])]),_:1}),t[2]||(t[2]=o("中寫道。",-1))]),t[19]||(t[19]=s("p",null,"“然而，對這些故障問題的快速調查發現，故障持續存在的主要原因不是人為失誤，而是由於管理失誤導致，如針對員工培訓投資不足，相關政策執行不力，管理程序老舊，低估一名合格員工的重要性，這一系列的管理問題導致了故障停機。” Heslin 繼續寫道。",-1)),t[20]||(t[20]=s("p",null,"正常運行時間協會指出，公司的 IT 基礎設施越複雜，特別是分佈式特性基礎設施，可能會越容易增加簡單的錯誤層出不窮而導致業務中斷的風險。同時指出公司需要意識到基礎設施越複雜所涉及的風險就越大。",-1)),t[21]||(t[21]=s("p",null,"並警告説，在人員配備方面，不要以超過公司吸引和應用資源來管理基礎設施的速度擴大關鍵 IT 能力，並在影響關鍵任務操作之前意識到任何人員和技能短缺。",-1)),t[22]||(t[22]=s("hr",null,null,-1)),s("p",null,[t[4]||(t[4]=o("via: ",-1)),r(e,{href:"https://www.networkworld.com/article/3444762/the-biggest-risk-to-uptime-your-staff.html"},{default:i(()=>[...t[3]||(t[3]=[o("https://www.networkworld.com/article/3444762/the-biggest-risk-to-uptime-your-staff.html",-1)])]),_:1})]),s("p",null,[t[9]||(t[9]=o("作者：",-1)),r(e,{href:"https://www.networkworld.com/author/Andy-Patrizio/"},{default:i(()=>[...t[5]||(t[5]=[o("Andy Patrizio",-1)])]),_:1}),t[10]||(t[10]=o(" 選題：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[6]||(t[6]=[o("lujun9972",-1)])]),_:1}),t[11]||(t[11]=o(" 譯者：",-1)),r(e,{href:"https://github.com/sthwhl"},{default:i(()=>[...t[7]||(t[7]=[o("sthwhl",-1)])]),_:1}),t[12]||(t[12]=o(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[8]||(t[8]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=o("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[o("LCTT",-1)])]),_:1}),t[16]||(t[16]=o(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[o("Linux中國",-1)])]),_:1}),t[17]||(t[17]=o(" 榮譽推出",-1))])])}const y=l(f,[["render",m]]);export{x as __pageData,y as default};
